SELECT i.group_id AS group_id, SUM(CASE WHEN i.user_id = #{userId} AND i.status = 'DEFENSE_WAIT' AND NOT EXISTS (SELECT 1 FROM tbl_defense d WHERE d.indictment_id = i.id) THEN 1 ELSE 0 END) AS my_defense_needed_count, SUM(CASE WHEN i.user_id <> #{userId} AND i.status = 'VOTING' AND NOT EXISTS (SELECT 1 FROM tbl_vote v WHERE v.indictment_id = i.id AND v.user_id = #{userId}) THEN 1 ELSE 0 END) AS pending_vote_count, SUM(CASE WHEN i.user_id <> #{userId} AND i.status = 'VOTING' AND EXISTS (SELECT 1 FROM tbl_vote v WHERE v.indictment_id = i.id AND v.user_id = #{userId}) THEN 1 ELSE 0 END) AS cast_vote_count FROM tbl_indictment i WHERE i.status IN ('DEFENSE_WAIT', 'VOTING') AND i.group_id IN
#{groupId}
GROUP BY i.group_id
